/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmdirSync, unlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const initial = [
  { id: 'z', title: 'Три / \"Цитата\"', pinned: true },
  { id: 'target', title: 'Два', pinned: false },
  { id: 'a', title: 'Один', pinned: false },
];
const dir = mkdtempSync('./.catalog-review.');
const path = join(dir, 'catalog.json');
const run = (code, ...args) => execFileSync(process.execPath, ['--input-type=module', '-e',
  \"import assert from 'node:assert/strict'; import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs'; const [path, ...args] = process.argv.slice(1); \" + code,
  path, ...args], { encoding: 'utf8' });
const reload = () => JSON.parse(run('console.log(JSON.stringify(loadCatalog(path)));'));
const write = cards => writeFileSync(path, JSON.stringify(cards));

write(initial);
try {
  for (const pinned of [true, false]) {
    const expected = [initial[0], { ...initial[1], pinned }, initial[2]];
    run(\"const cards = loadCatalog(path); assert.equal(cards[1].pinned, args[0] "'!== '"'true'); saveCatalog(path, setPinned(cards, 'target', args[0] === 'true'));\", String(pinned));
    assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), expected);
    const reloaded = reload();
    assert.deepEqual(reloaded, expected);
    console.log(pinned ? 'PIN' : 'UNPIN', 'disk and fresh process', JSON.stringify(reloaded));
  }
  const legacy = [initial[0], { id: 'target', title: 'Два' }, initial[2]];
  write(legacy);
  assert.deepEqual(reload(), initial);
  console.log('LEGACY missing pinned loaded as false');
  run(\"const cards = loadCatalog(path); assert.throws(() => setPinned(cards, 'missing', true), /Unknown card: missing/);\");
  assert.equal(readFileSync(path, 'utf8'), JSON.stringify(legacy));
  console.log('MISSING ID threw Unknown card: missing with a populated catalog');

  write([initial[0], initial[1], { ...initial[2], id: 'target' }]);
  run(\"saveCatalog(path, setPinned(loadCatalog(path), 'target', true));\");
  console.log('DUPLICATE ID exploratory', JSON.stringify(reload()));
} finally {
  unlinkSync(path);
  rmdirSync(dir);
}
NODE"

